ok = True
for m in d2:
    mid = m['id']
    for k in req_keys:
        if k not in m:
            print(f"{mid}: MISSING KEY {k}"); ok = False
    n = len(m['notes'])
    if not (6 <= n <= 8): print(f"{mid}: notes={n} FAIL"); ok = False
    for i,nt in enumerate(m['notes']):
        wc = len(nt['body'].split())
        if not (400 <= wc <= 900): print(f"{mid} note{i}: {wc} words FAIL"); ok = False
        if set(nt.keys()) != {'title','body'}: print(f"{mid} note{i}: keys {set(nt.keys())}"); ok = False
    if len(m['cards']) != 12: print(f"{mid}: cards={len(m['cards'])} FAIL"); ok = False
    q = len(m['quiz'])
    if not (9 <= q <= 10): print(f"{mid}: quiz={q} FAIL"); ok = False
    for qi in m['quiz']:
        if len(qi['choices']) != 4 or not (0 <= qi['answer'] <= 3): print(f"{mid}: bad quiz item"); ok = False
    dr = len(m['drills'])
    if not (2 <= dr <= 3): print(f"{mid}: drills={dr} FAIL"); ok = False
    for drl in m['drills']:
        it = len(drl['items'])
        if not (5 <= it <= 8): print(f"{mid} {drl['id']}: items={it} FAIL"); ok = False
        for itx in drl['items']:
            if set(itx.keys()) != {'prompt','answer','explain'}: print(f"{mid}: bad drill item keys"); ok = False
    lab = m['handsOnLab']
    st = len(lab['steps'])
    if not (8 <= st <= 14): print(f"{mid}: lab steps={st} FAIL"); ok = False
    for k in ['id','title','brief','steps','deliverable','checkpoint']:
        if k not in lab: print(f"{mid}: lab missing {k}"); ok = False
    v = len(m['videos'])
    if not (0 <= v <= 2): print(f"{mid}: videos={v} FAIL"); ok = False
    for vv in m['videos']:
        if vv.get('httpStatus') != 200: print(f"{mid}: video not 200"); ok = False
        for k in ['order','title','url','source','blurb','durationMin','watchBefore','verifiedUtc','httpStatus']:
            if k not in vv: print(f"{mid}: video missing {k}"); ok = False
    mt = m['mockTask']
    if len(mt['choices']) != 4 or not (0 <= mt['answer'] <= 3): print(f"{mid}: bad mockTask"); ok = False
